B.a_w=new A.cr("Hoa \u0110\xe0o",B.lS)
B.a_m=new A.cr("Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a ni\u1ec1m vui, h\u1ea1nh ph\xfac v\xe0 tinh th\u1ea7n \u0111o\xe0n k\u1ebft trong v\u0103n h\xf3a Vi\u1ec7t Nam. Trong \u0111\u1ea1i \u0110o\xe0n k\u1ebft d\xe2n t\u1ed9c Vi\u1ec7t Nam",B.cf)
B.a_B=new A.cr("Hoa \u0111\xe0o c\xf2n l\xe0 bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a tinh th\u1ea7n \u0111o\xe0n k\u1ebft, h\xf2a h\u1ee3p gi\u1eefa c\xe1c t\u1ea7ng l\u1edbp, c\xe1c t\u1ed5 ch\u1ee9c trong \u0111\u1ea1i gia \u0111\xecnh.",B.cf)
B.a_t=new A.cr("Hoa \u0111\xe0o v\u01b0\u01a1n m\xecnh gi\u1eefa ti\u1ebft tr\u1eddi l\u1ea1nh gi\xe1, t\u01b0\u1ee3ng tr\u01b0ng cho \xfd ch\xed ki\xean c\u01b0\u1eddng v\xe0 tinh th\u1ea7n v\u01b0\u1ee3t kh\xf3 c\u1ee7a d\xe2n t\u1ed9c Vi\u1ec7t Nam.",B.cf)
B.a_l=new A.cr("Hoa Mai",B.lS)
B.a_k=new A.cr("\u0110\u1ea1i di\u1ec7n cho s\u1ef1 kh\u1edfi \u0111\u1ea7u, ni\u1ec1m tin v\xe0 hy v\u1ecdng v\xe0o t\u01b0\u01a1ng lai.",B.cf)
B.a_p=new A.cr("Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a s\u1ef1 may m\u1eafn v\xe0 t\xe0i l\u1ed9c.",B.cf)
B.a_v=new A.cr("Hoa mai c\xf2n c\xf3 \xfd ngh\u0129a xua \u0111u\u1ed5i nh\u1eefng \u0111i\u1ec1u x\u1ea5u xa, kh\xf4ng t\u1ed1t \u0111\u1eb9p v\xe0 c\u1ea7u cho m\u1ed9t n\u0103m m\u1edbi lu\xf4n \u0111\u01b0\u1ee3c b\xecnh an, h\u1ea1nh ph\xfac v\xe0 ph\xe1t \u0111\u1ea1t.",B.cf)
