B.a_D=new A.cr("Bi\u1ec3u t\u01b0\u1ee3ng quy\u1ec1n l\u1ef1c, t\xedn ng\u01b0\u1ee1ng v\xe0 th\xe0nh t\u1ef1u v\u0103n minh c\u1ee7a c\u01b0 d\xe2n l\xfaa n\u01b0\u1edbc Vi\u1ec7t Nam c\xe1ch \u0111\xe2y h\u01a1n 2.000 n\u0103m.",B.cf)
B.a_O=new A.cr("tr\u1ed1ng \u0111\u1ed3ng l\xe0 bi\u1ec3u t\u01b0\u1ee3ng qu\xfd gi\xe1 cho n\xe9t \u0111\u1eb9p t\xe2m h\u1ed3n, phong t\u1ee5c t\u1eadp qu\xe1n c\u1ee7a ng\u01b0\u1eddi d\xe2n \u0111\u1ea5t Vi\u1ec7t, minh ch\u1ee9ng cho th\u1eddi k\u1ef3 d\u1ef1ng n\u01b0\u1edbc v\u0129 \u0111\u1ea1i c\u1ee7a cha \xf4ng.",B.cf)
